      '为了将可逆断裂的烯丙硫醚功能基团规律地引入聚合物主链中，他们加入了一种名为MDTO的开环单体。',
      '随着MDTO浓度的增加，聚合物的玻璃化转变温度（\\(T_g\\)）会系统性地降低，但所有样品在室温下都处于橡胶态，且能在常见有机溶剂中溶胀但不溶解，证明它们确实是交联聚合物。'
