      '非光降解证明：实验测得样品在拉伸和光照后的弹性模量甚至有轻微增加，这明确表明应力松弛并非由光降解引起。红外光谱分析也显示，光照后烯丙硫醚键并没有发生净损耗。',
      '制造应力梯度与光致形变：对处于应力下的光学致密样品进行单面光照，可以仅释放受光照一侧的应力。当外部应力移除后，样品会向未受光照的方向弯曲翘起，从而在不需要高温的情况下实现了形状改变或驱动（Actuation）。'
