      '图 a（交换机制）：进攻硫酯羰基后形成四面体中间体，再释放原来的硫醇端，新的硫酯连接由此形成。这是亲核加成–消除，不需要把它解释为二硫键交换或自由基 AFCT。',
      '图 b（模量）：保持总聚合物 3 wt%，将巯基过量从 0% 增至 200%，对应 SH:NB 从 1:1 增至 3:1；100% 过量就是 2:1。过量越多，有效桥接比例越低，G′ 大致由 3.8 kPa 降到 0.5 kPa。因此本组实验同时改变了刚度与松弛。',
      '图 c（应力松弛）：施加并保持 10% 剪切应变，记录 σ/σ₀。相同观察时间内，过量巯基更多的凝胶通常剩余应力更低。这测的是固定变形下的应力衰减，不是凝胶剩余质量，也不是直接数出多少交联键已断裂。',
      '图 d（拟合时间）：曲线用拉伸指数模型拟合，得到平均松弛时间约 2 × 10⁵–2 × 10⁶ s。这个量显著长于 5400 s 的实测窗口，是模型外推得到的特征时间，不能说作者真的持续测到了完全松弛，也不是半衰期。',
