      '图 b（曝光筛选）：比较 0、1、2.5、10、100 s。10 s 和 100 s 条件下，曲线已接近非适应性弹性对照。此筛选每个条件 n = 1，不能把轻微非单调差异解读为“10 s 比 100 s 更优”的统计结论。',
      '图 c（重复验证）：使用最终选定的 100 s 曝光，比较切换前后曲线。切换后，在同样的固定应变下，应力不再像原来的黏弹性网络那样下降。',
      '图 d（定量）：5400 s 时归一化剩余应力大致由 0.92 增至 0.98，差异显著，n = 3。这里剩余应力越高，代表松弛越弱，不能把柱子变高读成“松弛增强”。',
      '图 e（排除刚度变化）：封端前后 G′ 均约 1.9 kPa，统计标为 N.S.。这支持在该测量条件下调节松弛而不显著改变 G′；并不保证所有频率、应变或长期培养条件下的力学响应都完全相同。'
