      '现有连接方式的缺陷：目前常用的连接方法（如边缘缝合固定，或使用单独的非导电粘合剂）是次优的选择。缝合容易引发微小移动并具有侵入性，而添加额外的粘合剂层会增加器件与组织之间的物理距离，从而导致采集到的电信号严重衰减。'
