      '在体积膨胀方面，其横向膨胀率仅约为 1.05。将较亲水的 COOH 基团与亲水性较弱的 NHS 酯基团按 1:1 比例混合，赋予了 BAP 中等程度的吸水和膨胀性能，这有利于维持电学性能的稳定。',
      '与传统的聚丙烯酸（PAAc）相比，刷状 BAP 聚合物的吸水行为更加温和，扫描电子显微镜（SEM）图像（图 C）显示这可能是由刷状与非刷状聚合物结构造成的溶胀形貌和孔隙率差异所致。'
