      '与干燥表面不同，在湿润组织上，同时含有 COOH 和 NHS 酯侧链的薄膜黏附力最高，优于仅含单一功能基团的薄膜。这突显了亲水性 COOH 基团在吸收界面水分、促进初期黏附形成中的不可或缺性。',
      '该薄膜能够普遍应用于包括肌肉、心脏和皮肤在内的多种湿组织，并稳定提供高黏附强度（图 M）。'
