      '图 B 的转移特性曲线表明，BASC 混合薄膜（蓝线）与纯半导体 p(g2T-T) 薄膜（红线）在电学开关特性上高度一致，维持了理想的半导体性能。',
      '图 C 对比了核心性能指标，BASC 薄膜的电荷载流子迁移率保持在近 1 cm² V⁻¹ s⁻¹ 的高水平，与纯半导体薄膜相当，且其跨导（gm）指标甚至略高。',
      '图 D 为脉冲响应速度测试，在施加栅极电压突变时，BASC 薄膜的电流响应时间常数（τ = 12.9 ms）与纯半导体（τ = 11.4 ms）几乎处于同一水平，证实了生物黏附网络的加入并没有拖慢离子在薄膜内部的传输与掺杂速度。'
