      '图 G 的紫外-可见（UV-vis）吸收光谱则从短程结构物理解释了高迁移率的留存机制。BASC 薄膜在 0-0 与 0-1 跃迁吸收峰的相对强度上发生变化，表明其半导体相虽然失去了长程结晶，但在短距离内的分子聚集度反而更高，从而保障了电荷传输通道的顺畅。'
