      "type": "paragraph",
      "text": "这项研究将丰富的化学反应设计引入到了视网膜形态的器件中。它首次展示了一种能够通过化学、离子和电信号相互作用来识别颜色并进行记忆的流体器件，为未来开发能够与生物体连接的人工视网膜和人工眼球提供了重要的技术视角。"
