      "text": "由于混合导电聚合物在掺杂/去掺杂时，体载流子（空穴）密度的变化量极大（\\(\\Delta p > 10^{20} cm^{-3}\\)）。为了维持局部的电荷中性（electroneutrality），任何一处空穴浓度的增加或减少，都必须伴随着相等数量离子的流入或流出。因此，在光学显微镜下看到的透光率（空穴浓度）的空间变化，实质上就是离子运动轨迹的直接映射。"
