      "type": "paragraph",
      "text": "其中，\\(g_m = \\frac{\\partial I_D}{\\partial V_G}\\) 为器件的跨导，\\(g_{ds} = \\frac{\\partial I_D}{\\partial V_{DS}}\\) 为器件的输出电导。"
